/* Init sequence, waits for power-on (flag 0x20B3A) while still serving cat_parse (so PS works when
   off), then subsystem init and main_loop */

void app_main(void)

{
  wdt_kick();
  timers_init();
  FUN_fffb27df();
  eeprom_init();
  eeprom_load_all();
  key_task_init();
  sci_start_all();
  qmb_boot_init();
  while (g_ui.radio_on == 0) {
    displink_task();
    cat_parse();
    wdt_kick();
  }
  if (g_ui.defaults_loaded == 1) {
    g_ui.defaults_loaded = 0;
    eeprom_save_all();
    g_ui.freq_refresh_req = 1;
    wdt_kick();
  }
  shreg_bus_init();
  trx_init();
  sdr_init();
  dsp_link_init();
  portctl_init();
  dac_init_idle();
  keyer_init();
  tuner_init();
  menu_subsys_init();
  screensaver_timer_restart();
  main_loop();
  return;
}


