/* Super-loop (no RTOS): polls ~16 tasks incl. cat_parse each pass */

void main_loop(void)

{
  do {
    wdt_kick();
    io_task();
    sdr_task();
    dsp_link_poll();
    rf_ctrl_task();
    beep_task();
    cat_parse();
    ladder_key_task();
    scan_task();
    dispreq_e8_task();
    dispreq_e7_task();
    keyer_task();
    sd_menu_task();
    displink_task();
    key_task();
    tuner_task();
  } while( true );
}


